8|class GenerateRecurringTodos extends Command
9|{
10|    protected $signature = 'todos:generate-recurring {--dry-run : فقط نمایش موارد سررسید شده، بدون ایجاد}';
11|
12|    protected $description = 'Generate recurring todo instances from recurrence rules';
13|
14|    public function handle(): int
15|    {
16|        $dryRun = (bool) $this->option('dry-run');
17|        $now = now();
18|
19|        $due = Todo::query()
20|            ->where('recurrence_rule', '!=', 'none')
21|            ->whereNotNull('recurrence_rule')
22|            ->where(function ($q) use ($now) {
23|                $q->whereNull('last_generated_at')
24|                    ->orWhere('last_generated_at', '<=', $now);
25|            })
26|            ->get();
27|
28|        $this->info('Generating recurring todos...');
29|        $this->line("  Found {$due->count()} recurring todo(s) due for generation.");
30|
31|        if ($dryRun) {
32|            $this->warn('  Dry run — no todos were created.');
33|            $this->info('Recurring todo generation complete.');
34|
35|            return 0;
36|        }
37|
38|        $created = 0;
39|        foreach ($due as $template) {
40|            $next = $template->nextOccurrence() ?? $now;
41|
42|            Todo::create([
43|                'title' => $template->title,
44|                'start_at' => $next,
45|                'end_at' => null,
46|                'is_completed' => false,
47|                'unit_id' => $template->unit_id,
48|                'user_id' => $template->user_id,
49|                'recurrence_rule' => 'none',
50|            ]);
51|
52|            $template->update(['last_generated_at' => $next]);
53|            $created++;
