5|use App\Models\DailyReport;
6|use App\Models\Unit;
7|use App\Services\AccessService;
8|use Illuminate\Console\Command;
9|
10|class GenerateDailyReports extends Command
11|{
12|    protected $signature = 'reports:generate-daily {--unit= : فقط برای یک واحد خاص} {--dry-run : فقط نمایش، بدون ذخیره}';
13|
14|    protected $description = 'Generate daily reports for all accessible units';
15|
16|    public function handle(AccessService $access): int
17|    {
18|        $dryRun = (bool) $this->option('dry-run');
19|        $unitFilter = $this->option('unit');
20|
21|        $this->info('Generating daily reports...');
22|
23|        $unitIds = $unitFilter
24|            ? [(int) $unitFilter]
25|            : $access->accessibleUnitIds();
26|
27|        if (empty($unitIds)) {
28|            $this->warn('  No accessible units found — nothing to report.');
29|            $this->info('Daily report generation complete.');
30|
31|            return 0;
32|        }
33|
34|        $this->line('  Scoped to '.count($unitIds).' accessible unit(s).');
35|
36|        $today = now()->toDateString();
37|        $created = 0;
38|
39|        foreach ($unitIds as $unitId) {
40|            $unit = Unit::find($unitId);
41|            if (! $unit) {
42|                continue;
43|            }
44|
45|            $openTickets = $unit->tickets()->where('status', '!=', 'completed')->count();
46|            $openTodos = $unit->todos()->where('is_completed', false)->count();
47|
48|            $summary = "Unit {$unit->name}: {$openTickets} open tickets, {$openTodos} open todos.";
49|
50|            if ($dryRun) {
51|                $this->line("  [dry-run] {$summary}");
52|
53|                continue;
54|            }
55|
56|            if (DailyReport::where('unit_id', $unitId)->where('report_date', $today)->exists()) {
57|                continue;
58|            }
59|
60|            DailyReport::create([
61|                'unit_id' => $unitId,
62|                'report_date' => $today,
63|                'summary' => $summary,
64|                'payload' => [
65|                    'open_tickets' => $openTickets,
66|                    'open_todos' => $openTodos,
67|                ],
68|            ]);
69|
70|            $created++;
71|        }
72|
73|        $this->line("  Generated {$created} daily report(s).");
74|        $this->info('Daily report generation complete.');
75|
76|        return 0;
77|    }
