3|namespace App\Console\Commands;
4|
5|use App\Models\ActivityLog;
6|use App\Models\ActivityLogArchive;
7|use Illuminate\Console\Command;
8|
9|class ArchiveOldRecords extends Command
10|{
11|    protected $signature = 'data:archive {--months=12 : رکوردهای قدیمی‌تر از این تعداد ماه آرشیو شوند}
12|                                        {--dry-run : فقط شمارش کند، بدون انتقال}';
13|
14|    protected $description = 'Archive old activity log records to historical storage';
15|
16|    public function handle(): int
17|    {
18|        $months = (int) $this->option('months');
19|        $cutoff = now()->subMonths($months);
20|        $dryRun = (bool) $this->option('dry-run');
21|
22|        $query = ActivityLog::query()->where('created_at', '<', $cutoff);
23|        $count = $query->count();
24|
25|        $this->info("Archiving activity logs older than {$months} months (before {$cutoff->toDateTimeString()})...");
26|        $this->line("  Found {$count} record(s) eligible for archival.");
27|
28|        if ($dryRun) {
29|            $this->warn('  Dry run — no records were moved.');
30|            $this->info('Dry run complete.');
31|
32|            return 0;
33|        }
34|
35|        if ($count === 0) {
36|            $this->info('  Nothing to archive.');
37|            $this->info('Data archival complete.');
38|
39|            return 0;
40|        }
41|
42|        $moved = 0;
43|        $query->orderBy('id')->chunkById(1000, function ($logs) use (&$moved) {
44|            $rows = $logs->map(function (ActivityLog $log) {
45|                return [
46|                    'user_id' => $log->user_id,
47|                    'type' => $log->type,
48|                    'subject_type' => $log->subject_type,
49|                    'subject_id' => $log->subject_id,
50|                    'description' => $log->description,
51|                    'old_values' => $log->old_values,
52|                    'new_values' => $log->new_values,
53|                    'ip_address' => $log->ip_address,
54|                    'user_agent' => $log->user_agent,
55|                    'original_created_at' => $log->created_at,
56|                    'original_updated_at' => $log->updated_at,
57|                    'archived_at' => now(),
58|                ];
59|            })->all();
60|
61|            ActivityLogArchive::insert($rows);
62|            $ids = $logs->pluck('id')->all();
63|            ActivityLog::whereIn('id', $ids)->delete();
64|            $moved += count($ids);
65|        });
66|
67|        $this->line("  Archived {$moved} record(s) to activity_log_archives.");
68|        $this->info('Data archival complete.');
69|
70|        return 0;
71|    }
