29|                foreach ($fields as $field) {
30|                    if (! empty($hardware->$field) && is_string($hardware->$field)) {
31|                        $normalized = PersianNormalizer::normalize($hardware->$field);
32|                        if ($normalized !== $hardware->$field) {
33|                            $hardware->$field = $normalized;
34|                            $dirty = true;
35|                        }
36|                    }
37|                }
38|
39|                if ($dirty) {
40|                    $hardware->saveQuietly();
41|                    $count++;
