{"content": "1|<?php
2|
3|namespace App\Console\Commands;
4|
5|use App\Support\Testing\ResolvedTestDatabase;
6|use App\Support\Testing\TestDatabaseResolver;
7|use Illuminate\Console\Command;
8|use Illuminate\Support\Facades\Process;
9|use PDO;
10|use PDOException;
11|use Throwable;
12|
13|/**
14| * Environment preflight for `composer verify`.
15| *
16| * Runs BEFORE any destructive command. A missing test database otherwise shows
17| * up as "database h_dashboard_test does not exist" scattered through otherwise
18| * green tests — it reads exactly like a flake — and a mis-resolved database
19| * means `migrate:fresh` would drop the developer's real data.
20| *
21| * The exit codes are distinct on purpose: 2 means the environment is not fit to
22| * run the suite (a precondition), so a wrapper can tell "your machine is wrong"
23| * from "your code is wrong".
24| */
25|class VerifyPreflight extends Command
26|{
27|    public const EXIT_OK = 0;
28|
29|    public const EXIT_PRECONDITION_FAILED = 2;
30|
31|    /**
32|     * The database every test database is checked against.
33|     */
34|    private const MAINTENANCE_DATABASE = 'postgres';
35|
36|    protected $signature = 'verify:preflight';
37|
38|    protected $description = 'Check that this machine can run the test suite the way CI does';
39|
40|    public function handle(?TestDatabaseResolver $resolver = null): int
41|    {
42|        // Bound in tests to drive specific environments; unbound in production,
43|        // where the real shell environment is the only thing that matters.
44|        $resolver ??= TestDatabaseResolver::forCurrentProcess();
45|
46|        $target = $resolver->resolve();
47|        $expected = (string) config('verify.test_database', 'h_dashboard_test');
48|
49|        $this->line("Testing database: {$target->describe()}");
50|
51|        $failures = array_merge(
52|            $this->checkDriver($target),
53|            $this->checkName($target, $expected),
54|        );
55|
56|        if ($failures === []) {
57|            $failures = $this->checkServer($target);
58|        }
59|
60|        if ($failures !== []) {
61|            return $this->reportPreconditionFailure($failures, $target);
62|        }
63|
64|        $this->warnIfHooksAreMissing();
65|        $this->info('✅ Preflight passed — this machine can run the suite.');
66|
67|        return self::EXIT_OK;
68|    }
69|
70|    /**
71|     * @return array<int, string>
72|     */
73|    private function checkDriver(ResolvedTestDatabase $target): array
74|    {
75|        return $target->driver === 'pgsql'
76|            ? []
77|            : ["Driver is [{$target->driver}]; the suite requires pgsql (PostGIS)."];
78|    }
79|
80|    /**
81|     * @return array<int, string>
82|     */
83|    private function checkName(ResolvedTestDatabase $target, string $expected): array
84|    {
85|        if ($target->database === $expected) {
86|            return [];
87|        }
88|
89|        // The cause goes on its own line: it is the part the developer has to
90|        // act on, and a message that has to be read (not just spotted) is a
91|        // message that gets misread.
92|        return [
93|            "Database is [{$target->database}]; expected [{$expected}].",
94|            'An exported DB_DATABASE — or a DB_URL, which overrides every database variable — beats'
95|                .' the phpunit.xml value, because that <env> entry carries no force="true".',
96|            'Unset the variable, or set VERIFY_TEST_DATABASE if your test database has another name.',
97|        ];
98|    }
99|
100|    /**
101|     * Probed over a dedicated connection to the maintenance database, so the
102|     * check works even when the target database does not exist yet.
103|     *
104|     * @return array<int, string>
105|     */
106|    private function checkServer(ResolvedTestDatabase $target): array
107|    {
108|        try {
109|            $pdo = $this->maintenanceConnection($target);
110|        } catch (Throwable $e) {
111|            return ['Could not reach Postgres at '.$target->describe().': '.$e->getMessage()];
112|        }
113|
114|        $quoted = $pdo->quote($target->database);
115|
116|        // query() returns false on failure — never null — so the nullsafe
117|        // operator would be dead code that hides a real error.
118|        $exists = (bool) $pdo
119|            ->query("SELECT 1 FROM pg_database WHERE datname = {$quoted}")
120|            ->fetchColumn();
121|
122|        if (! $exists) {
123|            $create = 'psql -h '.escapeshellarg($target->host).' -U '.escapeshellarg($target->username)
124|                .' -d '.self::MAINTENANCE_DATABASE.' -c '
125|                .escapeshellarg("CREATE DATABASE {$target->database} WITH OWNER={$target->username};");
126|
127|            return [
128|                "Database [{$target->database}] does not exist.",
129|                'Create it once with:',
130|                '  '.$create,
131|            ];
132|        }
133|
134|        $postgis = $pdo->query("SELECT 1 FROM pg_available_extensions WHERE name = 'postgis'")->fetchColumn();
135|
136|        if (! $postgis) {
137|            return [
138|                "Postgres at {$target->host} has no postgis extension available.",
139|                'The migrations create the extension themselves, so this server is a plain',
140|                'postgres image: use postgis/postgis:16-3.4, as docker-compose does.',
141|            ];
142|        }
143|
144|        return [];
145|    }
146|
147|    private function maintenanceConnection(ResolvedTestDatabase $target): PDO
148|    {
149|        $dsn = sprintf(
150|            'pgsql:host=%s;port=%d;dbname=%s',
151|            $target->host,
152|            $target->port ?: 5432,
153|            self::MAINTENANCE_DATABASE,
154|        );
155|
156|        try {
157|            return new PDO($dsn, $target->username, $target->password);
158|        } catch (PDOException $e) {
159|            throw new PDOException($e->getMessage(), 0, $e);
160|        }
161|    }
162|
163|    /**
164|     * The pre-commit symlink is created by composer's post-install-cmd, so an
165|     * already-provisioned machine never gets it and the light layer is silently
166|     * absent. `composer hooks:install` is the supported path; this warning is
167|     * how its absence becomes visible.
168|     */
169|    private function warnIfHooksAreMissing(): void
170|    {
171|        if (config('verify.hooks.expect_installed') === false) {
172|            $this->reportMissingHooks('unset');
173|
174|            return;
175|        }
176|
177|        $expected = (string) config('verify.hooks.path', '.githooks');
178|        $configured = $this->hooksPath();
179|
180|        if ($configured === $expected && is_dir(base_path($expected))) {
181|            return;
182|        }
183|
184|        $this->reportMissingHooks($configured === '' ? 'unset' : $configured);
185|    }
186|
187|    private function reportMissingHooks(string $configured): void
188|    {
189|        $this->warn("⚠️  Git hooks are not active (core.hooksPath is {$configured}).");
190|        $this->line('    Run: composer hooks:install');
191|    }
192|
193|    private function hooksPath(): string
194|    {
195|        $git = base_path('.git');
196|
197|        if (! is_dir($git) && ! is_file($git)) {
198|            return '';
199|        }
200|
201|        try {
202|            // Process::run()'s second argument is a callback, not an argv array —
203|            // the command goes in the first one.
204|            return trim(Process::run(['git', 'config', '--get', 'core.hooksPath'])->output());
205|        } catch (Throwable) {
206|            return '';
207|        }
208|    }
209|
210|    /**
211|     * @param  array<int, string>  $failures
212|     */
213|    private function reportPreconditionFailure(array $failures, ResolvedTestDatabase $target): int
214|    {
215|        foreach ($failures as $failure) {
216|            $this->error($failure);
217|        }
218|
219|        $this->line("Resolved target: {$target->describe()}");
220|
221|        return self::EXIT_PRECONDITION_FAILED;
222|    }
