8|use Illuminate\Database\Eloquent\Factories\HasFactory;
9|use Illuminate\Database\Eloquent\Model;
10|use Illuminate\Database\Eloquent\Relations\BelongsTo;
11|use Illuminate\Database\Eloquent\Relations\HasMany;
12|
13|/**
14| * @property int $id
15| * @property string $title
16| * @property Carbon|null $start_at
17| * @property Carbon|null $end_at
18| * @property bool $is_completed
19| * @property int $unit_id
20| * @property Carbon|null $created_at
21| * @property Carbon|null $updated_at
22| * @property int $user_id
23| * @property string $recurrence_rule
24| * @property int $recurrence_interval
25| * @property Carbon|null $last_generated_at
26| * @property-read Unit $unit
27| * @property-read User $user
28| * @property-read Collection<int, Ticket> $tickets
29| *
30| * @method static \Illuminate\Database\Eloquent\Builder<static> where(string $column, mixed $value)
31| */
32|class Todo extends Model
33|{
34|    use HasFactory;
35|    use HasOrganizationalScope;
36|
37|    protected $fillable = [
38|        'title',
39|        'start_at',
40|        'end_at',
41|        'is_completed',
42|        'unit_id',
43|        'user_id',
44|        'recurrence_rule',
45|        'recurrence_interval',
46|        'last_generated_at',
47|    ];
48|
49|    protected $casts = [
50|        'start_at' => 'datetime',
51|        'end_at' => 'datetime',
52|        'is_completed' => 'boolean',
53|        'recurrence_interval' => 'integer',
54|        'last_generated_at' => 'datetime',
55|    ];
56|
57|    public function unit(): BelongsTo
58|    {
59|        return $this->belongsTo(Unit::class);
60|    }
61|
62|    public function user(): BelongsTo
63|    {
64|        return $this->belongsTo(User::class);
65|    }
66|
67|    // تیکت‌های مرتبط با این وظیفه
68|    public function tickets(): HasMany
69|    {
70|        return $this->hasMany(Ticket::class, 'task_id');
71|    }
72|
73|    /**
74|     * آیا این وظیفه تکرارشونده است؟
75|     */
76|    public function isRecurring(): bool
77|    {
78|        return $this->recurrence_rule !== null && $this->recurrence_rule !== 'none';
79|    }
80|
81|    /**
82|     * تاریخ سررسید بعدی برای تولید نمونه تکرارشونده.
83|     */
84|    public function nextOccurrence(): ?Carbon
85|    {
86|        if (! $this->isRecurring()) {
87|            return null;
88|        }
89|
90|        $base = $this->last_generated_at ?? $this->start_at ?? now();
91|        $interval = max(1, (int) $this->recurrence_interval);
92|
93|        return match ($this->recurrence_rule) {
94|            'daily' => $base->copy()->addDays($interval),
95|            'weekly' => $base->copy()->addWeeks($interval),
96|            'monthly' => $base->copy()->addMonths($interval),
97|            default => $base->copy()->addDays($interval),
98|        };
99|    }
