66|            'title' => 'HVAC inspection',
67|            'frequency' => 'monthly',
68|            'next_due_at' => now()->subDay(),
69|        ]);
70|
71|        $this->artisan('maintenance:generate-due', ['--dry-run' => true])
72|            ->expectsOutputToContain('Dry run')
73|            ->assertExitCode(0);
74|
75|        $this->assertDatabaseCount('tickets', 0);
