25|    config()->set('services.zabbix.in_item_id', null);
26|});
27|
28|test('sync exits 1 and warns when item ids are not configured', function () {
29|    // Service must never be touched in this path.
30|    app()->instance(ZabbixService::class, \Mockery::mock(ZabbixService::class));
31|
32|    $exitCode = Artisan::call('zabbix:sync');
33|
34|    expect($exitCode)->toBe(1)
35|        ->and(Artisan::output())->toContain('not configured');
36|});
37|
38|test('sync exits 1 when zabbix fetch fails', function () {
39|    config()->set('services.zabbix.out_item_id', '100');
40|    config()->set('services.zabbix.in_item_id', '200');
41|
42|    $mock = \Mockery::mock(ZabbixService::class);
43|    $mock->shouldReceive('getInterfaceTraffic')->andThrow(new \RuntimeException('connection refused'));
44|    app()->instance(ZabbixService::class, $mock);
45|
46|    $exitCode = Artisan::call('zabbix:sync');
47|
48|    expect($exitCode)->toBe(1)
49|        ->and(Artisan::output())->toContain('connection refused');
50|});
51|
52|test('sync exits 0 and reports fetched record count on success', function () {
53|    config()->set('services.zabbix.out_item_id', '100');
54|    config()->set('services.zabbix.in_item_id', '200');
55|
56|    $mock = \Mockery::mock(ZabbixService::class);
57|    $mock->shouldReceive('getInterfaceTraffic')->with('100')->andReturn([
58|        ['clock' => 1700000000, 'value' => '10'],
59|        ['clock' => 1700000060, 'value' => '20'],
60|    ]);
61|    $mock->shouldReceive('getInterfaceTraffic')->with('200')->andReturn([
62|        ['clock' => 1700000000, 'value' => '5'],
63|    ]);
64|    app()->instance(ZabbixService::class, $mock);
65|
66|    $exitCode = Artisan::call('zabbix:sync');
67|    $output = Artisan::output();
68|
69|    expect($exitCode)->toBe(0)
70|        ->and($output)->toContain('Fetched 3 traffic records.')
